"""WI-073 guarded, fixed-pressure regenerative/reheat steam-cycle calculation.

Source property bytes are embedded exactly below. No runtime network, HTML parser,
external property package, or generated-schema import is used. Component losses
and inlet-volume pump approximations follow the released WI-073 design.
"""
from __future__ import annotations
from typing import TYPE_CHECKING
if TYPE_CHECKING:
    from stellarator_tea.modules.mfe_matched_steam_cycle.matched_steam_cycle import Matched_Steam_CycleInput

import bisect
import hashlib
import json
import math
from functools import lru_cache
from pathlib import Path

AUTO_IMPLEMENTED = False
INPUT_NAMES = ('enabled', 'heat_available_MW', 'source_heat_MW', 'selected_recovered_MW', 'salt_flow_per_circuit', 'salt_circuit_count',
    'salt_hot_C', 'salt_return_C', 'salt_cp_kJ_kgK', 'main_pressure_MPa',
    'extraction_pressure_MPa', 'steam_temperature_C', 'reheat_temperature_C',
    'condenser_temperature_C', 'eta_hp', 'eta_lp', 'eta_condensate_pump',
    'eta_feedwater_pump', 'eta_pump_motor', 'eta_mechanical', 'eta_generator')
STATES = ('feed', 'main', 'hp', 'reheat', 'lp', 'condensate', 'condensate_pumped', 'heater')
STATE_OUTPUTS = tuple(name for state in STATES for name in
    (f'p_{state}_MPa', f'h_{state}_kJ_kg', f'mdot_{state}_kg_s') +
    (() if state == 'condensate_pumped' else (f't_{state}_C', f's_{state}_kJ_kgK')))
REAL_OUTPUTS = STATE_OUTPUTS + ('bleed_fraction', 'mdot_bleed_kg_s', 'salt_flow_total_kg_s',
    'salt_main_flow_kg_s', 'salt_reheat_flow_kg_s', 'q_main_MW', 'q_reheat_MW',
    'q_condenser_MW', 'p_hp_shaft_MW', 'p_lp_shaft_MW', 'p_condensate_shaft_MW',
    'p_feedwater_shaft_MW', 'p_condensate_electric_MW', 'p_feedwater_electric_MW',
    'p_cycle_pumps_MW', 'p_gross_MW', 'eta_gross', 'p_cycle_net_before_cooling_MW',
    'q_mechanical_loss_MW', 'q_generator_loss_MW', 'q_pump_motor_loss_MW',
    'q_rejection_before_cooling_MW', 'lp_quality', 'lp_moisture_fraction',
    'main_min_gap_K', 'reheat_min_gap_K', 'main_UA_MW_K', 'reheat_UA_MW_K',
    'salt_heat_residual_MW', 'heater_mass_residual_kg_s', 'heater_energy_residual_MW',
    'cycle_shaft_residual_MW', 'cycle_electric_residual_MW')
BOOL_OUTPUTS = ('active', 'main_UA_available', 'reheat_UA_available', 'main_admission_ok',
    'reheat_admission_ok', 'turbine_equipment_qualified', 'installed_sg_capacity_qualified')
# Parent replaces this tuple from the actual generated stencil. Declaration order
# is only the seed order, not a claim about the generator's eventual tuple order.
GENERATED_OUTPUT_ORDER = ('s_main_kJ_kgK', 'reheat_min_gap_K', 'mdot_heater_kg_s', 'h_hp_kJ_kg', 's_lp_kJ_kgK', 'p_condensate_pumped_MPa', 'mdot_main_kg_s', 'mdot_reheat_kg_s', 'q_generator_loss_MW', 't_feed_C', 'p_cycle_net_before_cooling_MW', 'main_UA_available', 'p_feedwater_electric_MW', 'q_rejection_before_cooling_MW', 'p_lp_MPa', 'lp_quality', 'h_condensate_pumped_kJ_kg', 't_heater_C', 'p_cycle_pumps_MW', 't_condensate_C', 'salt_reheat_flow_kg_s', 's_reheat_kJ_kgK', 'salt_main_flow_kg_s', 'p_gross_MW', 'p_feedwater_shaft_MW', 'h_main_kJ_kg', 't_reheat_C', 'installed_sg_capacity_qualified', 'p_hp_shaft_MW', 'p_main_MPa', 't_hp_C', 'mdot_feed_kg_s', 'mdot_bleed_kg_s', 'p_condensate_MPa', 'salt_heat_residual_MW', 'p_hp_MPa', 'active', 'eta_gross', 'h_lp_kJ_kg', 'mdot_condensate_kg_s', 'h_feed_kJ_kg', 'heater_energy_residual_MW', 'lp_moisture_fraction', 't_main_C', 'cycle_electric_residual_MW', 'p_feed_MPa', 'main_UA_MW_K', 'bleed_fraction', 'p_reheat_MPa', 'mdot_lp_kg_s', 'reheat_UA_MW_K', 'p_lp_shaft_MW', 'p_heater_MPa', 'q_main_MW', 'q_pump_motor_loss_MW', 'q_mechanical_loss_MW', 'p_condensate_electric_MW', 'main_min_gap_K', 'heater_mass_residual_kg_s', 's_hp_kJ_kgK', 'h_heater_kJ_kg', 'main_admission_ok', 'q_condenser_MW', 'mdot_hp_kg_s', 'h_condensate_kJ_kg', 'p_condensate_shaft_MW', 'turbine_equipment_qualified', 'h_reheat_kJ_kg', 'cycle_shaft_residual_MW', 'reheat_admission_ok', 's_heater_kJ_kgK', 'q_reheat_MW', 's_feed_kJ_kgK', 'salt_flow_total_kg_s', 'reheat_UA_available', 's_condensate_kJ_kgK', 'mdot_condensate_pumped_kg_s', 't_lp_C')


def finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f'WI-073 {name}: finite real required')
    return float(value)


def mode(value, name):
    value = finite(value, name)
    if value not in (0., 1.):
        raise ValueError(f'WI-073 {name}: mode must be exactly zero or one')
    return value == 1.


def efficiency(value, name):
    value = finite(value, name)
    if not 0 < value <= 1:
        raise ValueError(f'WI-073 {name}: efficiency must satisfy 0 < eta <= 1')
    return value


def positive(value, name):
    value = finite(value, name)
    if value <= 0:
        raise ValueError(f'WI-073 {name}: positive value required')
    return value


def balance(residual, scale, name):
    if not math.isfinite(residual) or abs(residual) > max(1e-8, 1e-12 * abs(scale)):
        raise ValueError(f'WI-073 {name}: balance residual {residual!r} exceeds arithmetic policy')


def verify_source_asset(path):
    """Generation/review hook: reject missing or changed canonical/staged bytes."""
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != SOURCE_ASSET_SHA256 or raw != SOURCE_ASSET_JSON.encode():
        raise ValueError('WI-073 source property asset identity mismatch')
    return SOURCE_ASSET_SHA256


@lru_cache(maxsize=1)
def property_tables():
    if hashlib.sha256(SOURCE_ASSET_JSON.encode()).hexdigest() != SOURCE_ASSET_SHA256:
        raise ValueError('WI-073 embedded property asset identity mismatch')
    return {name: table['rows'] for name, table in json.loads(SOURCE_ASSET_JSON)['tables'].items()}


def interpolate(rows, coordinate, value, output):
    value = finite(value, 'property '+coordinate)
    ordered = sorted(rows, key=lambda row: row[coordinate])
    points = [row[coordinate] for row in ordered]
    if not points or not points[0] <= value <= points[-1]:
        raise ValueError(f'WI-073 property domain: {coordinate}={value} outside supported {points[:1]}..{points[-1:]}')
    index = bisect.bisect_left(points, value)
    if index < len(points) and points[index] == value:
        return float(ordered[index][output])
    left, right = ordered[index-1:index+1]
    fraction = (value-left[coordinate])/(right[coordinate]-left[coordinate])
    return left[output] + fraction*(right[output]-left[output])


def state_temperature(rows, temperature, phase):
    selected = [row for row in rows if row['phase'] == phase]
    return {key: interpolate(selected, 'T', temperature, key) for key in ('T','P','h','s','v')}


def saturation_endpoints(rows):
    return (max((r for r in rows if r['phase']=='liquid'), key=lambda r:r['T']),
            min((r for r in rows if r['phase']=='vapor'), key=lambda r:r['T']))


def state_at(rows, coordinate, value):
    """Fixed-pressure liquid, two-phase and vapor inversion without clamping."""
    value = finite(value, 'property '+coordinate)
    liquid, vapor = saturation_endpoints(rows)
    if liquid[coordinate] <= value <= vapor[coordinate]:
        fraction = (value-liquid[coordinate])/(vapor[coordinate]-liquid[coordinate])
        return {key: liquid[key]+fraction*(vapor[key]-liquid[key]) for key in ('T','P','h','s','v')}
    phase = 'liquid' if value < liquid[coordinate] else 'vapor'
    selected = [row for row in rows if row['phase']==phase]
    return {key: interpolate(selected, coordinate, value, key) for key in ('T','P','h','s','v')}


def heat_profile(rows, inlet_h, outlet_h, salt_hot, salt_cold, duty, *, inlet_temperature=None, outlet_temperature=None):
    """Exact minima/integral for the full piecewise-linear enthalpy profile."""
    if outlet_h <= inlet_h or duty <= 0:
        raise ValueError('WI-073 heat profile: positive enthalpy rise and duty required')
    knots = sorted({inlet_h, outlet_h, *(r['h'] for r in rows if inlet_h < r['h'] < outlet_h)})
    temperatures = [state_at(rows, 'h', h)['T'] for h in knots]
    # Endpoints already have physical state temperatures. Do not round-trip
    # T -> h -> T and turn an exactly zero supplied approach into a positive ULP.
    if inlet_temperature is not None:
        temperatures[0] = inlet_temperature
    if outlet_temperature is not None:
        temperatures[-1] = outlet_temperature
    salt_temperatures = [salt_cold if h == inlet_h else salt_hot if h == outlet_h
        else salt_cold+(salt_hot-salt_cold)*(h-inlet_h)/(outlet_h-inlet_h) for h in knots]
    gaps = [salt-water for salt,water in zip(salt_temperatures,temperatures)]
    minimum = min(gaps)
    if minimum <= 0:
        return minimum, 0., False
    integrals = []
    for h0,h1,g0,g1 in zip(knots,knots[1:],gaps,gaps[1:]):
        difference = g1-g0
        if difference == 0:
            reciprocal_mean = 1/g0
        elif abs(difference/g0) < .5:
            reciprocal_mean = math.log1p(difference/g0)/difference
        else:
            reciprocal_mean = (math.log(g1)-math.log(g0))/difference
        integrals.append((h1-h0)*reciprocal_mean)
    return minimum, math.fsum(integrals)*duty/(outlet_h-inlet_h), True


def calculate(parameters):
    result = dict.fromkeys(REAL_OUTPUTS, 0.) | dict.fromkeys(BOOL_OUTPUTS, False)
    if not mode(parameters['enabled'], 'matched enabled'):
        return result
    p = {name: finite(parameters[name], name) for name in INPUT_NAMES}
    for name in INPUT_NAMES:
        if name.startswith('eta_'):
            efficiency(p[name], name)
    for name in ('heat_available_MW','salt_flow_per_circuit','salt_circuit_count','salt_cp_kJ_kgK'):
        positive(p[name], name)
    if p['main_pressure_MPa'] != 6.2 or p['extraction_pressure_MPa'] != .8:
        raise ValueError('WI-073 pressure domain: main/extraction must equal 6.2/0.8 MPa')
    if p['salt_hot_C'] <= p['salt_return_C']:
        raise ValueError('WI-073 salt boundary: hot temperature must exceed return temperature')
    salt_flow = p['salt_flow_per_circuit'] * p['salt_circuit_count']
    heat = p['heat_available_MW']
    plant_heat = p['source_heat_MW'] + p['selected_recovered_MW']
    balance(heat-plant_heat, max(abs(heat),abs(plant_heat)), 'plant and cycle heat join')
    salt_heat = salt_flow*p['salt_cp_kJ_kgK']*(p['salt_hot_C']-p['salt_return_C'])/1000
    salt_residual = heat-salt_heat
    balance(salt_residual, max(heat,salt_heat), 'salt input heat join')
    tables = property_tables()
    main_rows, extraction_rows, condenser_rows = (tables[k] for k in ('main','extraction','saturation'))
    heater_liquid, _ = saturation_endpoints(extraction_rows)
    _, main_vapor = saturation_endpoints(main_rows)
    if not main_vapor['T'] < p['steam_temperature_C'] <= 455:
        raise ValueError('WI-073 main steam: superheated supported temperature required')
    if not heater_liquid['T'] < p['reheat_temperature_C'] <= 455:
        raise ValueError('WI-073 reheat steam: superheated supported temperature required')
    if not 20 <= p['condenser_temperature_C'] <= 60:
        raise ValueError('WI-073 condenser: temperature outside 20..60 C')
    main = state_temperature(main_rows, p['steam_temperature_C'], 'vapor')
    reheated = state_temperature(extraction_rows, p['reheat_temperature_C'], 'vapor')
    condensate = state_temperature(condenser_rows, p['condenser_temperature_C'], 'liquid')
    condenser_vapor = state_temperature(condenser_rows, p['condenser_temperature_C'], 'vapor')
    if not condensate['P'] < .8 or not condensate['T'] < heater_liquid['T']:
        raise ValueError('WI-073 condensate pump: positive pressure rise required')
    wp_condensate = condensate['v']*(.8-condensate['P'])*1000/p['eta_condensate_pump']
    pumped_h = condensate['h']+wp_condensate
    hp_ideal = state_at(extraction_rows, 's', main['s'])
    hp_h = main['h']-p['eta_hp']*(main['h']-hp_ideal['h'])
    hp = state_at(extraction_rows, 'h', hp_h)
    if main['h'] <= hp_h:
        raise ValueError('WI-073 HP turbine: positive expansion work required')
    mixing_denominator = hp_h-pumped_h
    if mixing_denominator <= 0:
        raise ValueError('WI-073 open heater: nonpositive mixing enthalpy denominator')
    bleed = (heater_liquid['h']-pumped_h)/mixing_denominator
    if not 0 < bleed < 1:
        raise ValueError('WI-073 open heater: bleed fraction must lie strictly between zero and one')
    wp_feed = heater_liquid['v']*(6.2-.8)*1000/p['eta_feedwater_pump']
    feed = state_at(main_rows, 'h', heater_liquid['h']+wp_feed)
    ideal_quality = (reheated['s']-condensate['s'])/(condenser_vapor['s']-condensate['s'])
    if not 0 <= ideal_quality <= 1:
        raise ValueError('WI-073 LP ideal endpoint: outside supported two-phase entropy domain')
    ideal_lp_h = condensate['h']+ideal_quality*(condenser_vapor['h']-condensate['h'])
    lp_h = reheated['h']-p['eta_lp']*(reheated['h']-ideal_lp_h)
    quality = (lp_h-condensate['h'])/(condenser_vapor['h']-condensate['h'])
    if not 0 <= quality <= 1:
        raise ValueError('WI-073 LP actual endpoint: outside supported two-phase enthalpy domain')
    if reheated['h'] <= lp_h:
        raise ValueError('WI-073 LP turbine: positive expansion work required')
    lp = {'T':condensate['T'], 'P':condensate['P'], 'h':lp_h,
          's':condensate['s']+quality*(condenser_vapor['s']-condensate['s'])}
    q_main_specific = main['h']-feed['h']
    q_reheat_specific = reheated['h']-hp_h
    if q_main_specific <= 0 or q_reheat_specific <= 0:
        raise ValueError('WI-073 heat admission: both steam-generator and reheat duties must be positive')
    main_flow = heat*1000/(q_main_specific+(1-bleed)*q_reheat_specific)
    low_flow = main_flow*(1-bleed)
    bleed_flow = main_flow*bleed
    q_main, q_reheat = main_flow*q_main_specific/1000, low_flow*q_reheat_specific/1000
    q_condenser = low_flow*(lp_h-condensate['h'])/1000
    hp_shaft, lp_shaft = main_flow*(main['h']-hp_h)/1000, low_flow*(reheated['h']-lp_h)/1000
    cp_shaft, fp_shaft = low_flow*wp_condensate/1000, main_flow*wp_feed/1000
    cp_electric, fp_electric = cp_shaft/p['eta_pump_motor'], fp_shaft/p['eta_pump_motor']
    shaft = hp_shaft+lp_shaft
    generator_shaft = shaft*p['eta_mechanical']
    gross = generator_shaft*p['eta_generator']
    mechanical_loss, generator_loss = shaft-generator_shaft, generator_shaft-gross
    motor_loss = cp_electric+fp_electric-cp_shaft-fp_shaft
    rejection = q_condenser+mechanical_loss+generator_loss+motor_loss
    main_gap, main_ua, main_available = heat_profile(main_rows, feed['h'],main['h'],p['salt_hot_C'],p['salt_return_C'],q_main,inlet_temperature=feed['T'],outlet_temperature=p['steam_temperature_C'])
    reheat_gap, reheat_ua, reheat_available = heat_profile(extraction_rows,hp_h,reheated['h'],p['salt_hot_C'],p['salt_return_C'],q_reheat,inlet_temperature=hp['T'],outlet_temperature=p['reheat_temperature_C'])
    for name,state,flow in (('feed',feed,main_flow),('main',main,main_flow),('hp',hp,main_flow),
        ('reheat',reheated,low_flow),('lp',lp,low_flow),('condensate',condensate,low_flow),
        ('condensate_pumped',{'P':.8,'h':pumped_h},low_flow),('heater',heater_liquid,main_flow)):
        result.update({f'p_{name}_MPa':state['P'], f'h_{name}_kJ_kg':state['h'], f'mdot_{name}_kg_s':flow})
        if name != 'condensate_pumped':
            result.update({f't_{name}_C':state['T'], f's_{name}_kJ_kgK':state['s']})
    result.update(bleed_fraction=bleed, mdot_bleed_kg_s=bleed_flow,
        salt_flow_total_kg_s=salt_flow, salt_main_flow_kg_s=salt_flow*q_main/heat,
        salt_reheat_flow_kg_s=salt_flow*q_reheat/heat, q_main_MW=q_main,q_reheat_MW=q_reheat,
        q_condenser_MW=q_condenser,p_hp_shaft_MW=hp_shaft,p_lp_shaft_MW=lp_shaft,
        p_condensate_shaft_MW=cp_shaft,p_feedwater_shaft_MW=fp_shaft,
        p_condensate_electric_MW=cp_electric,p_feedwater_electric_MW=fp_electric,
        p_cycle_pumps_MW=cp_electric+fp_electric,p_gross_MW=gross,eta_gross=gross/heat,
        p_cycle_net_before_cooling_MW=gross-cp_electric-fp_electric,
        q_mechanical_loss_MW=mechanical_loss,q_generator_loss_MW=generator_loss,
        q_pump_motor_loss_MW=motor_loss,q_rejection_before_cooling_MW=rejection,
        lp_quality=quality,lp_moisture_fraction=1-quality,
        main_min_gap_K=main_gap,reheat_min_gap_K=reheat_gap,
        main_UA_MW_K=main_ua,reheat_UA_MW_K=reheat_ua,
        salt_heat_residual_MW=salt_residual,
        heater_mass_residual_kg_s=low_flow+bleed_flow-main_flow,
        heater_energy_residual_MW=(low_flow*pumped_h+bleed_flow*hp_h-main_flow*heater_liquid['h'])/1000,
        cycle_shaft_residual_MW=heat+cp_shaft+fp_shaft-shaft-q_condenser,
        cycle_electric_residual_MW=heat+cp_electric+fp_electric-gross-rejection,
        active=True, main_UA_available=main_available,reheat_UA_available=reheat_available,
        main_admission_ok=main_gap>0,reheat_admission_ok=reheat_gap>0)
    for name in REAL_OUTPUTS:
        if not math.isfinite(result[name]):
            raise ValueError('WI-073 nonfinite calculated output: '+name)
    balance(q_main+q_reheat-heat,heat,'admitted branch heat')
    balance(result['salt_main_flow_kg_s']+result['salt_reheat_flow_kg_s']-salt_flow,salt_flow,'salt branch flow')
    for name,scale in (('heater_mass_residual_kg_s',main_flow),('heater_energy_residual_MW',main_flow*heater_liquid['h']/1000),('cycle_shaft_residual_MW',heat),('cycle_electric_residual_MW',heat)):
        balance(result[name],scale,name)
    return result


def run_matched_steam_cycle(inputs: Matched_Steam_CycleInput) -> tuple[float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float, float]:
    result = calculate({name:getattr(inputs,name+'_in') for name in INPUT_NAMES})
    return tuple(result[name] for name in GENERATED_OUTPUT_ORDER)

# Exact normalized canonical source bytes; generated staging must preserve these.
